PREFIJO = {"TALLER": "EFITA", "COMERCIAL": "EFICO", "GERENCIA": "EFIGE", "IMPORTACION": "EFIIM"}


def codificar_pagos(apps, schema_editor):
    Pago = apps.get_model("core", "Pago")
    contador = {}
    for p in Pago.objects.order_by("fecha", "id"):
        rol = getattr(p.registrado_por, "rol", "") if p.registrado_por_id else ""
        if p.vestido_id or rol == "jefa_taller":
            p.origen = "TALLER"
        elif rol == "gerencia":
            p.origen = "GERENCIA"
        elif rol == "ti":
            p.origen = "IMPORTACION"
        else:
            p.origen = "COMERCIAL"
        prefijo = PREFIJO[p.origen]
        contador[prefijo] = contador.get(prefijo, 0) + 1
        p.codigo = f"{prefijo}-{contador[prefijo]:06d}"
        p.creado_en = timezone.make_aware(datetime.combine(p.fecha, time(12, 0)))
        p.save(update_fields=["origen", "codigo", "creado_en"])



